<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Edit Student</title><style>body{font-family:Arial;background:#f5f7fb;margin:0}.wrap{max-width:900px;margin:auto;padding:25px}.card{background:#fff;padding:22px;border-radius:12px;border:1px solid #e5e7eb}label{display:block;margin:10px 0 5px}input,select{width:100%;box-sizing:border-box;padding:9px;border:1px solid #d0d5dd;border-radius:7px}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:14px}.err{color:#b91c1c}.btn{padding:10px 15px;border:0;border-radius:7px;background:#2563eb;color:#fff;margin-top:18px}</style></head><body><div class="wrap"><div class="card"><h1>Edit Student #{{$student->student_no}}</h1>@if($errors->any())<div class="err">@foreach($errors->all() as $e)<div>{{$e}}</div>@endforeach</div>@endif<form method="POST" action="{{route('admin.students.update',$student->id)}}">@csrf @method('PUT')<div class="grid"><div><label>Name</label><input name="student_name" value="{{old('student_name',$student->student_name)}}" required></div><div><label>Phone</label><input name="student_phone" value="{{old('student_phone',$student->student_phone)}}" required></div><div><label>WhatsApp</label><input name="student_whatsapp" value="{{old('student_whatsapp',$student->student_whatsapp)}}" required></div><div><label>Gender</label><select name="student_gender"><option value="Male" @selected($student->student_gender==='Male')>Male</option><option value="Female" @selected($student->student_gender==='Female')>Female</option></select></div><div><label>Language</label><input name="student_language" value="{{$student->student_language}}"></div><div><label>Country</label><input name="student_country" value="{{$student->student_country}}"></div><div><label>Status</label><select name="student_status"><option value="1" @selected($student->student_status==1)>Active</option><option value="0" @selected($student->student_status==0)>Inactive</option><option value="2" @selected($student->student_status==2)>Blocked</option></select></div><div><label>Refer ID</label><input name="refer_id" value="{{$student->refer_id}}"></div><div><label>Trainer</label><select name="link_user_id"><option value="">None</option>@foreach($trainers as $t)<option value="{{$t->user_id}}" @selected($student->link_user_id==$t->user_id)>{{$t->firstname}} {{$t->lastname}} - {{$t->user_no}}</option>@endforeach</select></div><div><label>New Password</label><input type="password" name="password"></div><div><label>Confirm Password</label><input type="password" name="password_confirmation"></div></div><h3>Payment Medium</h3><div id="mediums">@foreach($mediums as $i=>$m)<div class="grid"><input name="payment_medium[{{$i}}][medium_name]" value="{{$m->medium_name}}" placeholder="Medium name"><input name="payment_medium[{{$i}}][medium_code]" value="{{$m->medium_code}}" placeholder="Medium number"><select name="payment_medium[{{$i}}][medium_status]"><option value="1" @selected($m->medium_status==1)>Active</option><option value="0" @selected($m->medium_status==0)>Inactive</option></select></div>@endforeach</div><button type="button" onclick="addMedium()">Add medium</button><br><button class="btn">Save</button> <a href="{{route('admin.students.index')}}">Cancel</a></form></div></div><script>let i={{count($mediums)}};function addMedium(){document.getElementById('mediums').insertAdjacentHTML('beforeend','<div class="grid"><input name="payment_medium['+i+'][medium_name]" placeholder="Medium name"><input name="payment_medium['+i+'][medium_code]" placeholder="Medium number"><select name="payment_medium['+i+'][medium_status]"><option value="1">Active</option><option value="0">Inactive</option></select></div>');i++}</script></body></html>